// B. Five user classes, four techniques; open questions about needs, not solutions.
const ELICITATION_PLAN = [
  {
    "userClass": "Receptionist",
    "technique": "Observation",
    "objective": "See how the morning phone rush, check-in and walk-ins are really handled today.",
    "questions": [
      "What do you do when two lines ring while a patient is at the desk?",
      "How do you decide who gets a free slot when a patient does not come?",
      "Which information do you look for most often during check-in?"
    ]
  },
  {
    "userClass": "Patient",
    "technique": "Questionnaire",
    "objective": "Learn how patients book today and what makes them miss appointments.",
    "questions": [
      "How do you usually book a visit today?",
      "What made you miss an appointment in the past?",
      "When would you like to be reminded before a visit?"
    ]
  },
  {
    "userClass": "Doctor",
    "technique": "Interview",
    "objective": "Understand how doctors plan their slots and write prescriptions.",
    "questions": [
      "How do you plan your working hours for a week?",
      "What information do you need before a patient enters the room?",
      "Which steps of writing a prescription take you the most time?"
    ]
  },
  {
    "userClass": "Pharmacist",
    "technique": "Interview",
    "objective": "Understand how prescriptions reach the pharmacy and are dispensed.",
    "questions": [
      "How do prescriptions reach you today?",
      "What happens when a medicine is out of stock?",
      "Which details of a prescription must you check before dispensing?"
    ]
  },
  {
    "userClass": "Clinic Manager",
    "technique": "Document analysis",
    "objective": "Study the current fee list and monthly reports to find the data the system must keep.",
    "questions": [
      "Which figures do you look at first in the monthly report?",
      "How often do service fees change, and who approves the change?",
      "What decisions do you make from the no-show numbers?"
    ]
  }
];

// C. Each question asks for the missing number or condition.
const FOLLOW_UPS = {
  V1: 'How many steps or how many seconds would feel quick enough to book a visit on your phone?',
  V2: 'How many hours before the appointment should the reminder arrive, and by which channel?',
  V3: 'Which services need a deposit, and how much is it for each?',
  V4: 'How many minutes late can a patient be before the slot is given away, and what happens to the fee?',
};

